   132	// A dependency-free stand-in for eslint and prettier, so the Chapter 6 hooks
   133	// have something real to run on a machine with no npm install.
   134	// Checks: no tab indentation, no trailing whitespace, file ends in one newline.
   135	import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
   136	import { join } from 'node:path';
   137	
   138	const fix = process.argv.includes('--fix');
   139	const targets = process.argv.slice(2).filter((a) => !a.startsWith('--'));
   140	
   141	function walk(dir) {
   142	  return readdirSync(dir).flatMap((e) => {
   143	    const p = join(dir, e);
   144	    if (statSync(p).isDirectory()) return walk(p);
   145	    return p.endsWith('.js') ? [p] : [];
   146	  });
   147	}
   148	
   149	const files = targets.length ? targets : [...walk('src'), ...walk('tests')];
   150	let problems = 0;
   151	
   152	for (const f of files) {
   153	  const before = readFileSync(f, 'utf8');
   154	  let after = before.replace(/\t/g, '  ').replace(/[ \t]+$/gm, '');
   155	  if (!after.endsWith('\n')) after += '\n';
   156	  after = after.replace(/\n{3,}$/, '\n');
   157	  if (after !== before) {
   158	    if (fix) writeFileSync(f, after);
   159	    else { console.error(`${f}: formatting`); problems += 1; }
   160	  }
   161	}
   162	
   163	if (problems && !fix) {
   164	  console.error(`${problems} file(s) need formatting. Run: npm run format`);
   165	  process.exit(1);
   166	}
   167	console.log(fix ? `formatted ${files.length} file(s)` : `${files.length} file(s) clean`);
